
.roster {
  padding: 12px 14px;
  border-bottom: 1px solid var(--line);
}

.section-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 9px;
}

.section-heading h2 {
  color: var(--book-blue);
  font-family: var(--font-display);
  font-size: 0.92rem;
  letter-spacing: 0.06em;
}

.section-heading span {
  color: var(--brass);
  font-family: var(--font-data);
  font-size: 0.62rem;
  letter-spacing: 0.12em;
}

.heading-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.toggle-unacquainted {
  padding: 1px 6px;
  font-family: var(--font-data);
  font-size: 0.56rem;
  color: var(--brass);
  background: transparent;
  border: 1px solid var(--line-soft);
  border-radius: 2px;
  cursor: pointer;
  line-height: 1.6;
  transition: color 160ms ease, border-color 160ms ease;
}

.toggle-unacquainted:hover {
  color: var(--ink);
  border-color: var(--brass);
}

.char-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
}

.char-card {
  min-width: 0;
  padding: 7px 8px;
  background: rgba(247, 240, 223, 0.46);
  border: 1px solid var(--line);
  border-radius: 2px;
  outline: none;
  transition: background-color 180ms ease, border-color 180ms ease, box-shadow 180ms ease;
}

.char-known {
  cursor: pointer;
}

.char-known:hover,
.char-known:focus-visible {
  background: rgba(247, 240, 223, 0.82);
  border-color: rgba(169, 139, 80, 0.82);
  box-shadow: inset 3px 0 var(--brass);
}

.char-active {
  box-shadow: inset 3px 0 rgba(143, 48, 48, 0.72);
}

.char-expanded {
  grid-column: 1 / -1;
  background: rgba(247, 240, 223, 0.9);
  border-color: rgba(64, 80, 90, 0.55);
}

.char-header {
  display: flex;
  min-width: 0;
  align-items: baseline;
  gap: 5px;
  margin-bottom: 4px;
}

.char-name {
  overflow-wrap: anywhere;
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 700;
}

.char-code {
  color: var(--annotation-red);
  font-size: 0.62rem;
}

.char-affection {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--ink-muted);
  font-family: var(--font-data);
  font-size: 0.61rem;
}

.affection-meter {
  height: 4px;
  min-width: 52px;
  flex: 1;
  overflow: hidden;
  background: rgba(70, 62, 50, 0.1);
}

.affection-fill {
  height: 100%;
  transition: width 180ms ease;
}

.char-locked {
  color: var(--ink-muted);
  font-size: 0.66rem;
}

.char-detail {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed rgba(92, 78, 57, 0.34);
}

.detail-ledger {
  display: grid;
  grid-template-columns: auto auto auto auto;
  justify-content: start;
  gap: 5px 9px;
  margin-bottom: 8px;
  color: var(--ink-muted);
  font-size: 0.66rem;
}

.detail-ledger strong {
  color: var(--ink);
}

.detail-ledger [class^='stage-'] {
  padding: 0 5px;
  color: var(--paper-light);
  background: var(--book-blue);
  border-radius: 2px;
}

.detail-ledger .stage-1 {
  color: var(--ink);
  background: var(--brass);
}

.detail-ledger .stage-2,
.detail-ledger .stage-3 {
  background: var(--annotation-red);
}

.body-status {
  display: grid;
  grid-template-columns: repeat(5, minmax(74px, 1fr));
  gap: 5px;
}

.body-part {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0 4px;
  min-width: 0;
  padding: 5px 6px;
  text-align: left;
  background: rgba(255, 255, 255, 0.28);
  border: 1px solid var(--line-soft);
  border-radius: 2px;
  cursor: pointer;
  transition: background-color 160ms ease, border-color 160ms ease, transform 160ms ease;
}

.body-part:hover {
  border-color: var(--brass);
}

.body-part:active {
  transform: translateY(1px);
}

.body-part:focus-visible {
  outline: 2px solid var(--book-blue);
  outline-offset: 1px;
}

.body-part.selected {
  background: var(--paper-light);
  border-color: var(--book-blue);
  box-shadow: inset 0 -2px var(--book-blue);
}

.body-part small {
  grid-column: 2;
  font-size: 0.58rem;
}

.body-纯洁 small {
  color: var(--book-blue);
}

.body-经验 small {
  color: var(--annotation-red);
  font-weight: 700;
}

.body-detail {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 7px;
  padding: 5px 7px;
  color: var(--ink-muted);
  font-size: 0.67rem;
  background: rgba(64, 80, 90, 0.06);
  border-left: 2px solid var(--book-blue);
}

.body-detail strong {
  color: var(--ink);
  font-family: var(--font-display);
}

@media (max-width: 600px) {
  .body-status {
    grid-template-columns: repeat(3, minmax(74px, 1fr));
  }
}

@media (max-width: 380px) {
  .char-grid {
    gap: 5px;
  }

  .char-card {
    padding: 6px;
  }

  .body-status {
    grid-template-columns: repeat(2, minmax(74px, 1fr));
  }
}
