
.action-buttons {
  display: flex;
  gap: 7px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--line);
}

.action-btn {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: 0;
  padding: 7px 6px 6px;
  font-family: var(--font-body);
  background: rgba(247, 240, 223, 0.42);
  border: 1px solid var(--line);
  border-radius: 2px;
  cursor: pointer;
  transition: background-color 180ms ease, border-color 180ms ease, transform 120ms ease;

  &:hover {
    background: rgba(247, 240, 223, 0.82);
  }

  &:active {
    transform: translateY(1px);
  }

  &:focus-visible {
    outline: 2px solid var(--book-blue);
    outline-offset: 1px;
  }
}

.action-tag {
  font-family: var(--font-data);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.06em;
}

.action-label {
  font-size: 0.62rem;
  color: var(--ink-muted);
}

.action-low {
  --action-accent: var(--book-blue);

  .action-tag {
    color: var(--book-blue);
  }

  &:hover {
    border-color: var(--book-blue);
    box-shadow: inset 0 0 0 2px rgba(64, 80, 90, 0.12);
  }
}

.action-high {
  --action-accent: var(--annotation-red);

  .action-tag {
    color: var(--annotation-red);
  }

  &:hover {
    border-color: var(--annotation-red);
    box-shadow: inset 0 0 0 2px rgba(143, 48, 48, 0.12);
  }
}

.action-pink {
  --action-accent: var(--jade);

  .action-tag {
    color: var(--jade);
  }

  &:hover {
    border-color: var(--jade);
    box-shadow: inset 0 0 0 2px rgba(65, 103, 86, 0.12);
  }
}

@media (max-width: 480px) {
  .action-buttons {
    flex-direction: column;
    gap: 5px;
  }

  .action-btn {
    flex-direction: row;
    justify-content: center;
    gap: 6px;
    padding: 6px 10px;
  }
}
